class Solution:
    def busyStudent(self, startTime: List[int], endTime: List[int], queryTime: int) -> int:
        m = max(endTime)
        diff = [0] * (m + 2)
        for s, e in zip(startTime, endTime):
            diff[s] += 1
            diff[e + 1] -= 1
        cur = 0
        for t in range(1, queryTime + 1):
            cur += diff[t]
        return cur

