        vector<int> diff(m + 2, 0);
        for (int i = 0; i < startTime.size(); ++i) {
            diff[startTime[i]]++;
            diff[endTime[i] + 1]--;
        }
        int cur = 0;
        for (int t = 1; t <= queryTime; ++t) cur += diff[t];
        return cur;
    }
};

