        int m = 0;
        for (int e : endTime) m = Math.max(m, e);
        int[] diff = new int[m + 2];
        for (int i = 0; i < startTime.length; i++) {
            diff[startTime[i]]++;
            diff[endTime[i] + 1]--;
        }
        int cur = 0;
        for (int t = 1; t <= queryTime; t++) cur += diff[t];
        return cur;
    }
}

